local lastteam = -1
Sprite_circle25 = 600 

local currteam = 1

function team(This, sender, messagetype, psize, params)
		if (messagetype == TaskMessage_FinishTurn) then
			currteam = -1
			if lastteam == 1 then
				currteam = 2
			else
				currteam = 1
			end
			lastteam = currteam
		end
		if (messagetype == TaskMessage_StartTurn) then
			currteam = -1
		end

end

function crate(This, sender, messagetype, psize, params)
if (messagetype == TaskMessage_UpdateNonCritical) then
	io.write(currteam .. "\n")
	if currteam ~= -1 then
		setTeamAmmo(currteam,This.unknown12C,0,getTeamAmmo(currteam,This.unknown12C,0)+This.unknown128)		
		This.posY = 9000 * 65536 -- send into obvlivion
	end
end
	
end


function initialize()
	CTaskTeam_RegisterCallback_vtable8(team)
	CTaskCrate_RegisterCallback_vtable8(crate)
	animations = {}
	sprites = {}
	return 0
end